                    Some(RustcSource::Discover) => {
                        Sysroot::discover_rustc(&cargo_toml, &config.extra_env)
                    }
                    None => None,
                };

                let rustc = match rustc_dir {
                    Some(rustc_dir) => Some({
                        let meta = CargoWorkspace::fetch_metadata(
                            &rustc_dir,
                            cargo_toml.parent(),
                            config,
                            progress,
